const resolveOrgContext = async (req, res, next) => {
  const orgId = req.headers['x-organization-id'];
  const membership = await db('organization_members').where({ organization_id: orgId, user_id: req.user.id }).first();
  if (!membership) return res.status(403).json({ error: 'You are not a member of this organization' });
  req.locals = { orgId };
  next();
};

app.get('/api/analytics/monthly', verifyToken, resolveOrgContext, async (req, res) => {
  const stats = await db('revenue_analytics').where({ organization_id: req.locals.orgId }).select('*');
  res.json(stats);
});
